CREATE TABLE public.bi_dashboard_widgets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,layout_id UUID NOT NULL REFERENCES public.bi_dashboard_layouts(id) ON DELETE CASCADE,widget_type TEXT NOT NULL,kpi_id UUID REFERENCES public.bi_kpi_definitions(id),position JSONB NOT NULL DEFAULT '{}',config JSONB NOT NULL DEFAULT '{}');
CREATE TABLE public.bi_report_runs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,report_id UUID NOT NULL REFERENCES public.bi_saved_reports(id) ON DELETE CASCADE,status TEXT NOT NULL CHECK(status IN('requested','generated','failed')),source_period JSONB NOT NULL DEFAULT '{}',row_count INTEGER,generated_at TIMESTAMPTZ,error_message TEXT);
CREATE TABLE public.bi_report_exports(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,report_run_id UUID NOT NULL REFERENCES public.bi_report_runs(id) ON DELETE CASCADE,format TEXT NOT NULL CHECK(format IN('csv','json','pdf_metadata','spreadsheet_metadata')),status TEXT NOT NULL CHECK(status IN('requested','pending','ready','failed')),metadata JSONB NOT NULL DEFAULT '{}',requested_by UUID REFERENCES auth.users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.bi_report_signoffs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,report_id UUID NOT NULL REFERENCES public.bi_saved_reports(id) ON DELETE CASCADE,status TEXT NOT NULL CHECK(status IN('draft','reviewed','approved','rejected')),reviewed_by UUID REFERENCES auth.users(id),approved_by UUID REFERENCES auth.users(id),signed_at TIMESTAMPTZ,UNIQUE(report_id));
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['bi_dashboard_widgets','bi_report_runs','bi_report_exports','bi_report_signoffs'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t);EXECUTE format('GRANT ALL ON public.%I TO service_role',t);EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (public.has_any_role(company_id,ARRAY[''admin'',''executive'',''managing_director'',''analyst'',''viewer'']::public.app_role[]))',t||'_read',t);END LOOP;END $$;
